@extends('layouts.app') @section('page_title','Physical Stock Counts') @section('content')<div class="card"><form method="POST" action="{{ route('procurement.stock-counts.store') }}" class="inline-form">@csrf<select name="store_id">@foreach($stores as $s)<option value="{{ $s->id }}">{{ $s->name }}</option>@endforeach</select><input name="notes" placeholder="Count notes"><button class="btn primary">Start Stock Count</button></form></div>@foreach($rows as $r)<div class="card"><h3>{{ $r->number }} · {{ $r->store->name }} <span class="badge">{{ $r->status }}</span></h3><form method="POST" action="{{ route('procurement.stock-counts.submit',$r) }}">@csrf<div class="table-wrap"><table><tr><th>Item</th><th>System</th><th>Counted</th><th>Variance</th></tr>@foreach($r->items as $line)<tr><td>{{ $line->inventoryItem->name }}</td><td>{{ number_format($line->system_quantity,4) }}</td><td><input name="counted[{{ $line->id }}]" type="number" step=".0001" value="{{ $line->counted_quantity }}" {{ $r->status==='posted'?'disabled':'' }}></td><td>{{ number_format($line->variance_quantity,4) }}</td></tr>@endforeach</table></div>@if($r->status!=='posted')<button class="btn primary">Post Count & Variances</button>@endif</form></div>@endforeach{{ $rows->links() }}@endsection